<script setup lang="ts">import{computed,onMounted,ref,watch}from'vue';import{api}from'../services/api';import{ExternalLink,RefreshCw}from'lucide-vue-next';const props=defineProps<{kind:string}>();const rows=ref<any[]>([]),device=ref<any>(null),loading=ref(true),error=ref('');const meta=computed(()=>({camera:['Câmera','Visualização disponível somente na rede local do dispositivo.'],varroa:['Varroa','Possíveis detecções; não representa taxa real de infestação.'],acid:['Ácido fórmico','Acompanhamento somente leitura. O servidor não aciona o mecanismo.'],alerts:['Alertas','Ocorrências e status de leitura.']} as any)[props.kind]);async function load(){loading.value=true;error.value='';try{if(props.kind==='camera'){device.value=(await api.get('/devices')).data[0]}else{const path=props.kind==='varroa'?'/detections':props.kind==='acid'?'/acid-releases':'/alerts';rows.value=(await api.get(path)).data}}catch{error.value='Não foi possível carregar os dados.'}finally{loading.value=false}}async function read(r:any){await api.patch(`/alerts/${r.id}/read`);r.is_read=true}onMounted(load);watch(()=>props.kind,load);const fmt=(v:any)=>v?new Date(v).toLocaleString('pt-BR'):'—';</script>
<template><main class="mx-auto max-w-5xl p-5 pb-28"><header class="mb-6"><h1 class="page-title">{{meta[0]}}</h1><p class="mt-1 text-sm text-slate-500">{{meta[1]}}</p></header><div v-if="loading" class="card animate-pulse">Carregando…</div><p v-else-if="error" class="card text-red-700">{{error}}</p><section v-else-if="kind==='camera'" class="card"><div class="aspect-video rounded-2xl bg-forest/10 grid place-items-center text-center p-5"><p>{{device?.local_camera_url?'Abra o stream local em uma nova janela.':'Endereço da câmera não configurado.'}}</p></div><div class="mt-4 flex flex-wrap gap-3"><a v-if="device?.local_camera_url" :href="device.local_camera_url" target="_blank" rel="noopener" class="btn inline-flex gap-2">Abrir câmera <ExternalLink/></a><button class="btn !bg-white !text-forest ring-1 ring-forest/20 inline-flex gap-2" @click="load"><RefreshCw/> Atualizar</button></div><p class="mt-4 text-xs text-slate-500">Navegadores podem bloquear conteúdo HTTP dentro de uma página HTTPS. A abertura direta evita o carregamento pelo servidor remoto; o vídeo nunca é retransmitido ao BPS.</p></section><section v-else class="space-y-3"><article v-for="r in rows" :key="r.id" class="card"><template v-if="kind==='varroa'"><div class="flex justify-between"><strong>{{r.positive_detections?'Possível Varroa detectada':'Sem Varroa detectada'}}</strong><span class="badge bg-mint">{{r.samples_analyzed?Math.round(r.positive_detections/r.samples_analyzed*100):0}}%</span></div><p class="mt-2 text-sm text-slate-500">{{r.positive_detections}} positivas em {{r.samples_analyzed}} amostras · {{fmt(r.detected_at)}}</p></template><template v-else-if="kind==='acid'"><strong>Liberação registrada</strong><p class="text-sm text-slate-500">{{r.released_amount??'Quantidade não medida'}} {{r.unit||''}} · {{fmt(r.released_at)}}</p></template><template v-else><div class="flex justify-between gap-3"><div><span class="badge bg-amber/20">{{r.severity}}</span><h2 class="mt-2 font-bold">{{r.title}}</h2><p class="text-sm text-slate-500">{{r.description}} · {{fmt(r.created_at)}}</p></div><button v-if="!r.is_read" class="text-sm font-semibold text-leaf" @click="read(r)">Marcar como lido</button></div></template></article><div v-if="!rows.length" class="card text-center text-slate-500">Nenhum registro encontrado.</div></section></main></template>
